+test('project symbol tries its positively-read concrete library before the specific fallback', async (t) => {
+	const opens: string[] = [];
+	let current: any;
+	let fallbacks = 0;
+	(globalThis as any).eda = {
+		lib_Symbol: {
+			get: async () => ({ uuid: 'SYM', libraryUuid: 'CONCRETE' }),
+			openInEditor: async () => { fallbacks++; },
+		},
+		lib_LibrariesList: { getPersonalLibraryUuid: async () => undefined },
+		dmt_SelectControl: { getCurrentDocumentInfo: async () => current },
+		dmt_EditorControl: {
+			openLibraryDocument: async (library: string) => {
+				opens.push(library);
+				if (library !== 'CONCRETE') return undefined;
+				current = { uuid: 'SYM', documentType: 2, parentLibraryUuid: 'CONCRETE', tabId: 'SYM@CONCRETE' };
+				return 'SYM@CONCRETE';
+			},
+			activateDocument: async () => true,
+		},
+	};
+	t.after(() => { delete (globalThis as any).eda; });
+	assert.equal(await activateLibraryDocument('SYM', 'project', '2' as any, 2 as any, 'symbol'), 'SYM@CONCRETE');
+	assert.deepEqual(opens, ['project', 'CONCRETE']);
+	assert.equal(fallbacks, 0);
+});
+
